static const char nx_str_1041[7289] = "// std.args: command-line argument parsing, written in Nexium.\n//\n// `import std.args` then:\n//\n//     var p = args.Parser.new(os.args())\n//     let verbose = p.flag(\"--verbose\", \"-v\")\n//     let level = p.option(\"--level\", \"-l\") orelse \"info\"\n//     let files = p.rest()\n//\n// Long options take `--name value` or `--name=value`; short ones `-n value`.\n// Everything after `--` is positional. Unknown options stay in `rest()`\n// so the caller can report them.\n\npub struct Parser {\n    argv: [][]u8\n    used: List(bool)\n}\n\nimpl Parser {\n    /// Wrap `os.args()`; the program name in `argv[0]` is skipped.\n    pub fn new(argv: [][]u8) -> Parser {\n        var used = List(bool).with_capacity(argv.len)\n        for _ in argv { used.append(false) }\n        if used.len > 0 { used[0] = true }\n        return Parser{ .argv = argv, .used = used }\n    }\n\n    fn matches(self: *Self, i: usize, long: []u8, short: []u8) -> bool {\n        let a = self.argv[i]\n        return a == long or (short.len > 0 and a == short)\n    }\n\n    /// True when the flag is present (any number of times).\n    pub fn flag(self: *mut Self, long: []u8, short: []u8) -> bool {\n        var found = false\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if self.matches(i, long, short) {\n                self.used[i] = true\n                found = true\n            }\n        }\n        return found\n    }\n\n    /// How many times the flag appears (`-vvv` counts as three).\n    pub fn count(self: *mut Self, long: []u8, short: []u8) -> usize {\n        var n: usize = 0\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if self.matches(i, long, short) {\n                self.used[i] = true\n                n += 1\n            } else if short.len == 2 and a.len > 2 and a[0] == '-' and a[1] != '-' {\n                // stacked short flags: -vvv\n                var all = true\n                for c in a[1..] { if c != short[1] { all = false } }\n                if all {\n                    self.used[i] = true\n                    n += a.len - 1\n                }\n            }\n        }\n        return n\n    }\n\n    /// The value of `--name value`, `--name=value`, or `-n value`; the last one wins.\n    pub fn option(self: *mut Self, long: []u8, short: []u8) -> ?[]u8 {\n        var value: ?[]u8 = null\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if self.matches(i, long, short) {\n                self.used[i] = true\n                if i + 1 < self.argv.len {\n                    self.used[i + 1] = true\n                    value = self.argv[i + 1]\n                }\n            } else if a.len > long.len and a.starts_with(long) and a[long.len] == '=' {\n                self.used[i] = true\n                value = a[long.len + 1..]\n            }\n        }\n        return value\n    }\n\n    /// Every value of a repeatable option, in order.\n    pub fn options(self: *mut Self, long: []u8, short: []u8) -> List([]u8) {\n        var out = List([]u8).new()\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if self.matches(i, long, short) {\n                self.used[i] = true\n                if i + 1 < self.argv.len {\n                    self.used[i + 1] = true\n                    out.append(self.argv[i + 1])\n                }\n            } else if a.len > long.len and a.starts_with(long) and a[long.len] == '=' {\n                self.used[i] = true\n                out.append(a[long.len + 1..])\n            }\n        }\n        return out\n    }\n\n    /// An option parsed as an integer; `error.InvalidInput` when present but not a number.\n    pub fn int_option(self: *mut Self, long: []u8, short: []u8) -> !?i64 {\n        let raw = self.option(long, short) orelse return null\n        let v = raw.parse_int(i64) catch |e| return error.InvalidInput\n        return v\n    }\n\n    /// Arguments not consumed by any query, plus everything after `--`.\n    pub fn rest(self: *Self) -> List([]u8) {\n        var out = List([]u8).new()\n        var after_dashes = false\n        for a, i in self.argv {\n            if after_dashes {\n                out.append(a)\n            } else if a == \"--\" {\n                after_dashes = true\n            } else if !self.used[i] {\n                out.append(a)\n            }\n        }\n        return out\n    }\n\n    /// Unconsumed arguments that look like options: the ones the program did not ask for.\n    pub fn unknown_options(self: *Self) -> List([]u8) {\n        var out = List([]u8).new()\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if !self.used[i] and a.len > 1 and a[0] == '-' { out.append(a) }\n        }\n        return out\n    }\n}\n\n/// Render a usage line and option table from (flags, description) rows.\npub fn usage(program: []u8, summary: []u8, rows: [][]u8) -> String {\n    var out = String.new()\n    out.append(\"usage: \")\n    out.append(program)\n    out.append(\" \")\n    out.append(summary)\n    out.append(\"\\n\")\n    var i: usize = 0\n    while i + 1 < rows.len {\n        out.append(\"  \")\n        out.append(rows[i])\n        for _ in rows[i].len..22 { out.push_byte(' ') }\n        out.append(rows[i + 1])\n        out.append(\"\\n\")\n        i += 2\n    }\n    return out\n}\n\n/// The environment as a map, from `os.environ()`.\npub fn env_map() -> Map(String, String) {\n    var m = Map(String, String).new()\n    for entry in os.environ() {\n        var i: usize = 0\n        while i < entry.len and entry[i] != '=' { i += 1 }\n        if i == 0 or i >= entry.len { continue }\n        m.put(String.from(entry[0..i]), String.from(entry[i + 1..entry.len]))\n    }\n    return m\n}\n\ntest \"env map\" {\n    let m = env_map()\n    expect(m.len > 0)\n}\n\ntest \"flags and options\" {\n    let argv = [\"prog\", \"-v\", \"--level\", \"debug\", \"--name=nx\", \"in.txt\", \"-v\", \"--\", \"-x\"]\n    var p = Parser.new(argv[..])\n    expect(p.flag(\"--verbose\", \"-v\"))\n    expect(!p.flag(\"--quiet\", \"-q\"))\n    expect_eq(p.option(\"--level\", \"-l\") orelse \"none\", \"debug\")\n    expect_eq(p.option(\"--name\", \"-n\") orelse \"none\", \"nx\")\n    expect(p.option(\"--missing\", \"\") == null)\n    let rest = p.rest()\n    expect_eq(rest.len, 2)\n    expect_eq(rest[0], \"in.txt\")\n    expect_eq(rest[1], \"-x\")\n}\n\ntest \"counts and repeats\" {\n    let argv = [\"prog\", \"-vvv\", \"-I\", \"a\", \"-I\", \"b\", \"--include=c\"]\n    var p = Parser.new(argv[..])\n    expect_eq(p.count(\"--verbose\", \"-v\"), 3)\n    let incs = p.options(\"--include\", \"-I\")\n    expect_eq(incs.len, 3)\n    expect_eq(incs[2], \"c\")\n    expect_eq(p.rest().len, 0)\n}\n\ntest \"integers and unknowns\" {\n    let argv = [\"prog\", \"--jobs\", \"8\", \"--bad\", \"--depth=x\"]\n    var p = Parser.new(argv[..])\n    let jobs = try p.int_option(\"--jobs\", \"-j\")\n    expect_eq(jobs orelse 0, 8)\n    let none = try p.int_option(\"--none\", \"\")\n    expect(none == null)\n    var bad = false\n    _ = p.int_option(\"--depth\", \"-d\") catch |e| {\n        bad = true\n        null\n    }\n    expect(bad)\n    let unk = p.unknown_options()\n    expect_eq(unk.len, 1)\n    expect_eq(unk[0], \"--bad\")\n}\n\ntest \"usage text\" {\n    let rows = [\"-v, --verbose\", \"say more\", \"-l, --level L\", \"log level\"]\n    let u = usage(\"tool\", \"[options] FILE\", rows[..])\n    expect(u.starts_with(\"usage: tool [options] FILE\\n\"))\n    expect(u.find(\"  -v, --verbose\") != null)\n    expect(u.find(\"log level\\n\") != null)\n}\n";
static const char nx_str_1042[6122] = "// std.bytes: encodings and byte-level utilities, written in Nexium.\n//\n// `import std.bytes` then `bytes.hex(data)`, `bytes.base64(data)`, ...\n// Decoders return `error.InvalidInput` on malformed text.\n\nconst HEX = \"0123456789abcdef\"\nconst B64 = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"\n\n/// Lower-case hexadecimal, two characters per byte.\npub fn hex(data: []u8) -> String {\n    var out = String.with_capacity(data.len * 2)\n    for b in data {\n        out.push_byte(HEX[(b >> 4) as usize])\n        out.push_byte(HEX[(b & 15) as usize])\n    }\n    return out\n}\n\nfn hex_value(c: u8) -> ?u8 {\n    if c >= '0' and c <= '9' { return c - '0' }\n    if c >= 'a' and c <= 'f' { return c - 'a' + 10 }\n    if c >= 'A' and c <= 'F' { return c - 'A' + 10 }\n    return null\n}\n\n/// Bytes from hexadecimal text (either case, even length).\npub fn unhex(text: []u8) -> !String {\n    if text.len % 2 != 0 { return error.InvalidInput }\n    var out = String.with_capacity(text.len / 2)\n    var i: usize = 0\n    while i < text.len {\n        let hi = hex_value(text[i]) orelse return error.InvalidInput\n        let lo = hex_value(text[i + 1]) orelse return error.InvalidInput\n        out.push_byte(hi * 16 + lo)\n        i += 2\n    }\n    return out\n}\n\n/// Standard base64 with `=` padding.\npub fn base64(data: []u8) -> String {\n    var out = String.with_capacity((data.len + 2) / 3 * 4)\n    var i: usize = 0\n    while i + 3 <= data.len {\n        let n = (data[i] as u32) << 16 | (data[i + 1] as u32) << 8 | data[i + 2] as u32\n        out.push_byte(B64[(n >> 18) as usize & 63])\n        out.push_byte(B64[(n >> 12) as usize & 63])\n        out.push_byte(B64[(n >> 6) as usize & 63])\n        out.push_byte(B64[n as usize & 63])\n        i += 3\n    }\n    let rest = data.len - i\n    if rest == 1 {\n        let n = (data[i] as u32) << 16\n        out.push_byte(B64[(n >> 18) as usize & 63])\n        out.push_byte(B64[(n >> 12) as usize & 63])\n        out.append(\"==\")\n    } else if rest == 2 {\n        let n = (data[i] as u32) << 16 | (data[i + 1] as u32) << 8\n        out.push_byte(B64[(n >> 18) as usize & 63])\n        out.push_byte(B64[(n >> 12) as usize & 63])\n        out.push_byte(B64[(n >> 6) as usize & 63])\n        out.append(\"=\")\n    }\n    return out\n}\n\nfn b64_value(c: u8) -> ?u32 {\n    if c >= 'A' and c <= 'Z' { return (c - 'A') as u32 }\n    if c >= 'a' and c <= 'z' { return (c - 'a') as u32 + 26 }\n    if c >= '0' and c <= '9' { return (c - '0') as u32 + 52 }\n    if c == '+' { return 62 }\n    if c == '/' { return 63 }\n    return null\n}\n\n/// Bytes from standard base64 (padding optional).\npub fn unbase64(text: []u8) -> !String {\n    var out = String.with_capacity(text.len / 4 * 3)\n    var acc: u32 = 0\n    var bits: u32 = 0\n    for c in text {\n        if c == '=' or c == '\\n' or c == '\\r' { continue }\n        let v = b64_value(c) orelse return error.InvalidInput\n        acc = (acc << 6) | v\n        bits += 6\n        if bits >= 8 {\n            bits -= 8\n            out.push_byte(((acc >> bits) & 255) as u8)\n        }\n    }\n    return out\n}\n\n/// FNV-1a, 32 bits: a fast non-cryptographic hash.\npub fn fnv1a(data: []u8) -> u32 {\n    var h: u32 = 2166136261\n    for b in data {\n        h ^= b as u32\n        h *%= 16777619\n    }\n    return h\n}\n\n/// CRC-32 (IEEE), as used by zip and PNG.\npub fn crc32(data: []u8) -> u32 {\n    var crc: u32 = 0xFFFFFFFF\n    for b in data {\n        crc ^= b as u32\n        for _ in 0..8 {\n            let mask = 0 -% (crc & 1)\n            crc = (crc >> 1) ^ (0xEDB88320 & mask)\n        }\n    }\n    return crc ^ 0xFFFFFFFF\n}\n\n/// Big-endian 32-bit read.\npub fn read_u32_be(data: []u8, at: usize) -> u32 {\n    return (data[at] as u32) << 24 | (data[at + 1] as u32) << 16 | (data[at + 2] as u32) << 8 | data[at + 3] as u32\n}\n\n/// Little-endian 32-bit read.\npub fn read_u32_le(data: []u8, at: usize) -> u32 {\n    return (data[at + 3] as u32) << 24 | (data[at + 2] as u32) << 16 | (data[at + 1] as u32) << 8 | data[at] as u32\n}\n\n/// Append a big-endian 32-bit value.\npub fn write_u32_be(out: *mut String, v: u32) {\n    out.push_byte((v >> 24) as u8)\n    out.push_byte(((v >> 16) & 255) as u8)\n    out.push_byte(((v >> 8) & 255) as u8)\n    out.push_byte((v & 255) as u8)\n}\n\n/// Append a little-endian 32-bit value.\npub fn write_u32_le(out: *mut String, v: u32) {\n    out.push_byte((v & 255) as u8)\n    out.push_byte(((v >> 8) & 255) as u8)\n    out.push_byte(((v >> 16) & 255) as u8)\n    out.push_byte((v >> 24) as u8)\n}\n\n/// Bytes that differ, for a compact diff of two buffers.\npub fn first_difference(a: []u8, b: []u8) -> ?usize {\n    let n = if a.len < b.len { a.len } else { b.len }\n    for i in 0..n { if a[i] != b[i] { return i } }\n    if a.len != b.len { return n }\n    return null\n}\n\ntest \"hex\" {\n    expect_eq(hex(\"AZ\"), \"415a\")\n    expect_eq(hex(\"\"), \"\")\n    let back = try unhex(\"415A\")\n    expect_eq(back, \"AZ\")\n    expect((unhex(\"41z\") catch |e| String.from(@errorName(e))) == \"InvalidInput\")\n    expect((unhex(\"4\") catch |e| String.from(@errorName(e))) == \"InvalidInput\")\n}\n\ntest \"base64 round trips\" {\n    expect_eq(base64(\"Man\"), \"TWFu\")\n    expect_eq(base64(\"Ma\"), \"TWE=\")\n    expect_eq(base64(\"M\"), \"TQ==\")\n    expect_eq(base64(\"\"), \"\")\n    expect_eq(base64(\"hello, nexium\"), \"aGVsbG8sIG5leGl1bQ==\")\n    let back = try unbase64(\"aGVsbG8sIG5leGl1bQ==\")\n    expect_eq(back, \"hello, nexium\")\n    let unpadded = try unbase64(\"TWE\")\n    expect_eq(unpadded, \"Ma\")\n    expect((unbase64(\"T*E=\") catch |e| String.from(@errorName(e))) == \"InvalidInput\")\n}\n\ntest \"hashes\" {\n    expect_eq(fnv1a(\"hello\"), 1335831723)\n    expect_eq(crc32(\"123456789\"), 0xCBF43926)\n    expect_eq(crc32(\"\"), 0)\n}\n\ntest \"integers in and out\" {\n    var buf = String.new()\n    write_u32_be(&mut buf, 0x01020304)\n    write_u32_le(&mut buf, 0x01020304)\n    expect_eq(buf.len, 8)\n    expect_eq(read_u32_be(buf, 0), 0x01020304)\n    expect_eq(read_u32_le(buf, 4), 0x01020304)\n    expect_eq(buf[4], 4)\n}\n\ntest \"first_difference\" {\n    expect_eq(first_difference(\"abc\", \"abd\") orelse 99, 2)\n    expect_eq(first_difference(\"abc\", \"abcd\") orelse 99, 3)\n    expect(first_difference(\"abc\", \"abc\") == null)\n}\n";
static const char nx_str_1043[3] = "fs";
static const char nx_str_1044[11537] = "// std.fs: files, directories and paths, written in Nexium.\n//\n// `import std.fs` then:\n//\n//     if fs.exists(\"notes.txt\") { ... }\n//     try fs.make_dirs(\"out/logs\")\n//     for name in try fs.list(\"out\") { ... }\n//     for path in try fs.walk(\"src\") { ... }        // every file, recursively\n//     let cfg = fs.join(fs.parent(argv0), \"app.toml\")\n//\n// The platform calls are the `io.*` builtins (documented in the language\n// reference); this module adds paths, sorted listings, recursive create and\n// remove, and a walker. Paths are byte strings; `/` and `\\` both separate\n// components on every platform, and results use `/` unless the input used `\\`.\n\n// ------------------------------------------------------------------ queries\n\n/// Is there a file or directory at `path`?\npub fn exists(path: []u8) -> bool {\n    return io.file_kind(path) != 0\n}\n\n/// Is `path` an existing regular file (anything that is not a directory)?\npub fn is_file(path: []u8) -> bool {\n    return io.file_kind(path) == 1\n}\n\n/// Is `path` an existing directory?\npub fn is_dir(path: []u8) -> bool {\n    return io.file_kind(path) == 2\n}\n\n/// The size of a file in bytes.\npub fn size(path: []u8) -> !u64 {\n    return io.file_size(path)\n}\n\n/// The modification time in milliseconds since the epoch.\npub fn modified(path: []u8) -> !i64 {\n    return io.file_modified(path)\n}\n\n// ------------------------------------------------------------------ contents\n\n/// The whole file as a String.\npub fn read(path: []u8) -> !String {\n    return io.read_file(path)\n}\n\n/// The lines of a file, without their line endings.\npub fn read_lines(path: []u8) -> !List(String) {\n    let text = try io.read_file(path)\n    var out = List(String).new()\n    for l in text.lines() { out.append(String.from(l)) }\n    return out\n}\n\n/// Write (replace) a file.\npub fn write(path: []u8, data: []u8) -> !void {\n    return io.write_file(path, data)\n}\n\n/// Append to a file, creating it when missing.\npub fn append(path: []u8, data: []u8) -> !void {\n    return io.append_file(path, data)\n}\n\n/// Copy a file's contents to a new path (the destination is replaced).\npub fn copy(from: []u8, to: []u8) -> !void {\n    let data = try io.read_file(from)\n    return io.write_file(to, data)\n}\n\n// ------------------------------------------------------------------ directories\n\n/// The names in a directory, sorted, without `.` and `..`.\npub fn list(path: []u8) -> !List(String) {\n    var names = try io.list_dir(path)\n    sort_names(&mut names)\n    return names\n}\n\n/// Create one directory; fine when it already exists.\npub fn make_dir(path: []u8) -> !void {\n    return io.make_dir(path)\n}\n\n/// Create a directory and every missing parent.\npub fn make_dirs(path: []u8) -> !void {\n    if path.len == 0 or is_dir(path) { return }\n    let p = parent(path)\n    if p.len > 0 and p.len < path.len and !is_dir(p) { try make_dirs(p) }\n    return io.make_dir(path)\n}\n\n/// Remove a file or an empty directory.\npub fn remove(path: []u8) -> !void {\n    if is_dir(path) { return io.remove_dir(path) }\n    return io.remove_file(path)\n}\n\n/// Remove a file, or a directory with everything in it.\npub fn remove_all(path: []u8) -> !void {\n    if is_dir(path) {\n        let names = try io.list_dir(path)\n        for n in names {\n            let child = join(path, n)\n            try remove_all(child)\n        }\n        return io.remove_dir(path)\n    }\n    if exists(path) { return io.remove_file(path) }\n}\n\n/// Rename or move a file or directory (an existing destination file is replaced).\npub fn rename(from: []u8, to: []u8) -> !void {\n    return io.rename(from, to)\n}\n\n/// Every file under `root`, recursively, as paths joined onto `root`, sorted\n/// directory by directory. Directories themselves are not listed.\npub fn walk(root: []u8) -> !List(String) {\n    var out = List(String).new()\n    try walk_into(root, &mut out)\n    return out\n}\n\nfn walk_into(dir: []u8, out: *mut List(String)) -> !void {\n    let names = try list(dir)\n    for n in names {\n        let child = join(dir, n)\n        if is_dir(child) {\n            try walk_into(child, out)\n        } else {\n            out.append(child)\n        }\n    }\n}\n\n/// The current working directory.\npub fn cwd() -> !String {\n    return io.cwd()\n}\n\n/// The directory for temporary files.\npub fn temp_dir() -> String {\n    return io.temp_dir()\n}\n\n/// A fresh path in the temporary directory, `<temp>/<prefix><number>`, that\n/// does not exist yet. The caller creates it.\npub fn temp_path(prefix: []u8) -> String {\n    let base = io.temp_dir()\n    var n = time.now()\n    while true {\n        var candidate = join(base, prefix)\n        candidate.append(format(\"{}\", .{n}))\n        if !exists(candidate) { return candidate }\n        n += 1\n    }\n}\n\n// ------------------------------------------------------------------ paths\n\nfn is_sep(c: u8) -> bool {\n    return c == '/' or c == '\\\\'\n}\n\n/// The separator a path uses: `\\` when it contains one, else `/`.\nfn sep_of(path: []u8) -> u8 {\n    for c in path { if c == '\\\\' { return '\\\\' } }\n    return '/'\n}\n\n/// Does the path start at a root (`/x`, `C:\\x`, `C:/x`, `\\\\server`)?\npub fn is_absolute(path: []u8) -> bool {\n    if path.len == 0 { return false }\n    if is_sep(path[0]) { return true }\n    return path.len >= 3 and path[1] == ':' and is_sep(path[2])\n}\n\n/// `dir/name`; a separator is added only when needed, and an absolute `name`\n/// replaces `dir`.\npub fn join(dir: []u8, name: []u8) -> String {\n    if dir.len == 0 or is_absolute(name) { return String.from(name) }\n    var out = String.from(dir)\n    if name.len == 0 { return out }\n    if !is_sep(dir[dir.len - 1]) { out.push_byte(sep_of(dir)) }\n    out.append(name)\n    return out\n}\n\n/// Everything before the last separator: `a/b/c.txt` -> `a/b`, `c.txt` -> ``,\n/// `/c.txt` -> `/`.\npub fn parent(path: []u8) -> []u8 {\n    var end = path.len\n    while end > 0 and is_sep(path[end - 1]) { end -= 1 }\n    var i = end\n    while i > 0 and !is_sep(path[i - 1]) { i -= 1 }\n    if i == 0 { return path[0..0] }\n    var j = i\n    while j > 1 and is_sep(path[j - 1]) { j -= 1 }\n    if j == 1 and is_sep(path[0]) { return path[0..1] }\n    if j >= 2 and path[j - 1] == ':' { return path[0..j + 1] }\n    return path[0..j]\n}\n\n/// The last component: `a/b/c.txt` -> `c.txt`.\npub fn base_name(path: []u8) -> []u8 {\n    var end = path.len\n    while end > 0 and is_sep(path[end - 1]) { end -= 1 }\n    var i = end\n    while i > 0 and !is_sep(path[i - 1]) { i -= 1 }\n    return path[i..end]\n}\n\n/// The extension without the dot: `a/b.tar.gz` -> `gz`, `Makefile` -> ``.\npub fn extension(path: []u8) -> []u8 {\n    let name = base_name(path)\n    var i = name.len\n    while i > 0 {\n        i -= 1\n        if name[i] == '.' {\n            if i == 0 { return name[0..0] }\n            return name[i + 1..name.len]\n        }\n    }\n    return name[0..0]\n}\n\n/// The base name without its extension: `a/b.tar.gz` -> `b.tar`.\npub fn stem(path: []u8) -> []u8 {\n    let name = base_name(path)\n    var i = name.len\n    while i > 0 {\n        i -= 1\n        if name[i] == '.' {\n            if i == 0 { return name }\n            return name[0..i]\n        }\n    }\n    return name\n}\n\n/// The path with its extension replaced (or added): `a/b.txt`, `md` -> `a/b.md`.\npub fn with_extension(path: []u8, ext: []u8) -> String {\n    let e = extension(path)\n    var out = String.from(if e.len > 0 { path[0..path.len - e.len - 1] } else { path })\n    if ext.len > 0 {\n        out.push_byte('.')\n        out.append(ext)\n    }\n    return out\n}\n\n/// Collapse `.` and `..` components and repeated separators:\n/// `a/./b/../c//d` -> `a/c/d`. A leading `..` is kept.\npub fn normalize(path: []u8) -> String {\n    let sep = sep_of(path)\n    var parts = List([]u8).new()\n    var start: usize = 0\n    var i: usize = 0\n    while i <= path.len {\n        if i == path.len or is_sep(path[i]) {\n            let part = path[start..i]\n            if part.len == 0 or part == \".\" {\n                // skip\n            } else if part == \"..\" {\n                if parts.len > 0 and parts[parts.len - 1] != \"..\" { _ = parts.pop() }\n                else if ! (path.len > 0 and is_sep(path[0])) { parts.append(part) }\n            } else {\n                parts.append(part)\n            }\n            start = i + 1\n        }\n        i += 1\n    }\n    var out = String.new()\n    if path.len > 0 and is_sep(path[0]) { out.push_byte(sep) }\n    for p, k in parts {\n        if k > 0 { out.push_byte(sep) }\n        out.append(p)\n    }\n    if out.len == 0 { out.push_byte('.') }\n    return out\n}\n\n// ------------------------------------------------------------------ helpers\n\nfn less(a: []u8, b: []u8) -> bool {\n    var i: usize = 0\n    while i < a.len and i < b.len {\n        if a[i] != b[i] { return a[i] < b[i] }\n        i += 1\n    }\n    return a.len < b.len\n}\n\nfn sort_names(names: *mut List(String)) {\n    var i: usize = 1\n    while i < names.len {\n        var j = i\n        while j > 0 and less(names[j], names[j - 1]) {\n            let s = names.remove(j)\n            names.insert(j - 1, s)\n            j -= 1\n        }\n        i += 1\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"path parts\" {\n    expect_eq(parent(\"a/b/c.txt\"), \"a/b\")\n    expect_eq(parent(\"c.txt\"), \"\")\n    expect_eq(parent(\"/c.txt\"), \"/\")\n    expect_eq(parent(\"a/b/\"), \"a\")\n    expect_eq(parent(\"C:\\\\x\\\\y.txt\"), \"C:\\\\x\")\n    expect_eq(parent(\"C:\\\\y.txt\"), \"C:\\\\\")\n    expect_eq(base_name(\"a/b/c.txt\"), \"c.txt\")\n    expect_eq(base_name(\"a/b/\"), \"b\")\n    expect_eq(extension(\"a/b.tar.gz\"), \"gz\")\n    expect_eq(extension(\"Makefile\"), \"\")\n    expect_eq(extension(\".bashrc\"), \"\")\n    expect_eq(stem(\"a/b.tar.gz\"), \"b.tar\")\n    expect_eq(stem(\".bashrc\"), \".bashrc\")\n    expect_eq(with_extension(\"a/b.txt\", \"md\"), \"a/b.md\")\n    expect_eq(with_extension(\"a/b\", \"md\"), \"a/b.md\")\n    expect_eq(with_extension(\"a/b.txt\", \"\"), \"a/b\")\n}\n\ntest \"join and absolute\" {\n    expect_eq(join(\"a\", \"b\"), \"a/b\")\n    expect_eq(join(\"a/\", \"b\"), \"a/b\")\n    expect_eq(join(\"\", \"b\"), \"b\")\n    expect_eq(join(\"a\", \"/b\"), \"/b\")\n    expect_eq(join(\"C:\\\\x\", \"y\"), \"C:\\\\x\\\\y\")\n    expect(is_absolute(\"/x\"))\n    expect(is_absolute(\"C:\\\\x\"))\n    expect(is_absolute(\"C:/x\"))\n    expect(!is_absolute(\"x/y\"))\n    expect(!is_absolute(\"\"))\n}\n\ntest \"normalize\" {\n    expect_eq(normalize(\"a/./b/../c//d\"), \"a/c/d\")\n    expect_eq(normalize(\"/a/../..\"), \"/\")\n    expect_eq(normalize(\"../a\"), \"../a\")\n    expect_eq(normalize(\"a/..\"), \".\")\n    expect_eq(normalize(\"C:\\\\a\\\\..\\\\b\"), \"C:\\\\b\")\n}\n\ntest \"files and directories\" {\n    let root = temp_path(\"nxfs-\")\n    try make_dirs(join(root, \"deep/er\"))\n    expect(is_dir(root))\n    expect(is_dir(join(root, \"deep/er\")))\n    let f = join(root, \"deep/er/note.txt\")\n    try write(f, \"one\\ntwo\\n\")\n    try append(f, \"three\\n\")\n    expect(is_file(f))\n    expect(!is_dir(f))\n    expect_eq(try size(f), 14)\n    let lines = try read_lines(f)\n    expect_eq(lines.len, 3)\n    expect_eq(lines[2], \"three\")\n    try copy(f, join(root, \"copy.txt\"))\n    let names = try list(root)\n    expect_eq(names.len, 2)\n    expect_eq(names[0], \"copy.txt\")\n    expect_eq(names[1], \"deep\")\n    let files = try walk(root)\n    expect_eq(files.len, 2)\n    expect_eq(base_name(files[1]), \"note.txt\")\n    try rename(join(root, \"copy.txt\"), join(root, \"moved.txt\"))\n    expect(!exists(join(root, \"copy.txt\")))\n    expect(exists(join(root, \"moved.txt\")))\n    var missing = false\n    _ = size(\"definitely/missing\") catch |e| {\n        missing = e == error.NotFound\n        0\n    }\n    expect(missing)\n    try remove_all(root)\n    expect(!exists(root))\n}\n";
