static const char nx_str_1062[5894] = "// std.testing: conveniences for `test` blocks, written in Nexium.\n//\n// `import std.testing` then, inside a test:\n//\n//     testing.expect_approx(area, 3.14159, 0.001)\n//     testing.expect_err(i32, parse(\"nope\"))\n//     testing.expect_contains(output, \"42 items\")\n//     testing.expect_lines(rendered, expected)    // reports the first differing line\n//     testing.expect_snapshot(\"report\", rendered)  // compares to snapshots/report.txt\n//     try testing.snapshot(\"report\", rendered)     // the same, as an error union\n//\n// Snapshots live in `snapshots/<name>.txt` under the current directory. A\n// missing file is written and the test passes; a mismatch fails with the\n// first differing line and how to accept the new output. Set\n// `NX_UPDATE_SNAPSHOTS=1` to rewrite them all.\n\nimport std.fs\n\n/// Are two floats within `eps` of each other?\npub fn approx(a: f64, b: f64, eps: f64) -> bool {\n    let d = if a > b { a - b } else { b - a }\n    return d <= eps\n}\n\n/// Panics unless `a` and `b` are within `eps`.\npub fn expect_approx(a: f64, b: f64, eps: f64) {\n    if !approx(a, b, eps) { panic(format(\"expected {} to be within {} of {}\", .{a, eps, b})) }\n}\n\n/// Did the call fail? (Any error counts.)\npub fn is_err(comptime T: type, own r: !T) -> bool {\n    _ = r catch { return true }\n    return false\n}\n\n/// Panics unless the result is an error.\npub fn expect_err(comptime T: type, own r: !T) {\n    if !is_err(T, r) { panic(\"expected an error but the call succeeded\") }\n}\n\n/// Panics unless the result is exactly `err`.\npub fn expect_error(comptime T: type, own r: !T, err: error) {\n    _ = r catch |e| {\n        if e != err { panic(format(\"expected error {} but got {}\", .{err, e})) }\n        return\n    }\n    panic(format(\"expected error {} but the call succeeded\", .{err}))\n}\n\n/// Panics unless `hay` contains `needle`.\npub fn expect_contains(hay: []u8, needle: []u8) {\n    if hay.find(needle) == null { panic(format(\"expected to find {} in {}\", .{needle, hay})) }\n}\n\n/// Compares line by line; panics naming the first line that differs.\npub fn expect_lines(actual: []u8, expected: []u8) {\n    let a = actual.lines()\n    let e = expected.lines()\n    var i: usize = 0\n    while i < a.len and i < e.len {\n        if a[i] != e[i] { panic(format(\"line {} differs:\\n  expected: {}\\n  actual:   {}\", .{i + 1, e[i], a[i]})) }\n        i += 1\n    }\n    if a.len != e.len { panic(format(\"expected {} line(s) but got {}\", .{e.len, a.len})) }\n}\n\n/// Compare `actual` to `<dir>/<name>.txt`; write it when missing or when\n/// NX_UPDATE_SNAPSHOTS is set.\npub fn snapshot_in(dir: []u8, name: []u8, actual: []u8) -> !void {\n    var file = fs.join(dir, name)\n    file.append(\".txt\")\n    let update = os.env(\"NX_UPDATE_SNAPSHOTS\") != null\n    if update or !fs.exists(file) {\n        try fs.make_dirs(dir)\n        try fs.write(file, actual)\n        eprintln(\"wrote snapshot {}\", .{file})\n        return\n    }\n    let expected = try fs.read(file)\n    expect_lines(actual, expected)\n}\n\n/// `snapshot_in(\"snapshots\", name, actual)`.\npub fn snapshot(name: []u8, actual: []u8) -> !void {\n    return snapshot_in(\"snapshots\", name, actual)\n}\n\n/// `snapshot_in`, in the `expect_` form: a mismatch fails the test naming\n/// the file, the first differing line and how to accept the new output;\n/// a file that cannot be read or written fails it too, instead of\n/// returning an error for the test to handle.\npub fn expect_snapshot_in(dir: []u8, name: []u8, actual: []u8) {\n    var file = fs.join(dir, name)\n    file.append(\".txt\")\n    let update = os.env(\"NX_UPDATE_SNAPSHOTS\") != null\n    if update or !fs.exists(file) {\n        fs.make_dirs(dir) catch { panic(format(\"snapshot {}: cannot create the directory {}\", .{file, dir})) }\n        fs.write(file, actual) catch { panic(format(\"snapshot {}: cannot write it\", .{file})) }\n        eprintln(\"wrote snapshot {}\", .{file})\n        return\n    }\n    let expected = fs.read(file) catch { panic(format(\"snapshot {}: cannot read it\", .{file})) }\n    let a = actual.lines()\n    let e = expected[..].lines()\n    var i: usize = 0\n    while i < a.len and i < e.len {\n        if a[i] != e[i] {\n            panic(format(\"snapshot {} differs at line {}:\\n  expected: {}\\n  actual:   {}\\nNX_UPDATE_SNAPSHOTS=1 accepts the new output\", .{file, i + 1, e[i], a[i]}))\n        }\n        i += 1\n    }\n    if a.len != e.len {\n        panic(format(\"snapshot {}: expected {} line(s) but got {}; NX_UPDATE_SNAPSHOTS=1 accepts the new output\", .{file, e.len, a.len}))\n    }\n}\n\n/// `expect_snapshot_in(\"snapshots\", name, actual)`.\npub fn expect_snapshot(name: []u8, actual: []u8) {\n    expect_snapshot_in(\"snapshots\", name, actual)\n}\n\n// ------------------------------------------------------------------ tests\n\nfn parse_digit(s: []u8) -> !i32 {\n    if s.len != 1 or s[0] < '0' or s[0] > '9' { return error.InvalidInput }\n    return (s[0] - '0') as i32\n}\n\ntest \"snapshots\" {\n    let dir = fs.join(io.temp_dir()[..], \"nx-testing-snapshots\")\n    fs.remove_all(dir[..]) catch { }\n    expect_snapshot_in(dir[..], \"report\", \"one\\ntwo\\n\") // written\n    expect_snapshot_in(dir[..], \"report\", \"one\\ntwo\\n\") // read back, equal\n    expect(fs.exists(fs.join(dir[..], \"report.txt\")))\n    fs.remove_all(dir[..]) catch { }\n}\n\ntest \"floats and errors\" {\n    expect(approx(1.0, 1.0001, 0.001))\n    expect(!approx(1.0, 1.1, 0.001))\n    expect_approx(0.1 + 0.2, 0.3, 0.000001)\n    expect(is_err(i32, parse_digit(\"x\")))\n    expect(!is_err(i32, parse_digit(\"7\")))\n    expect_err(i32, parse_digit(\"nope\"))\n    expect_error(i32, parse_digit(\"nope\"), error.InvalidInput)\n}\n\ntest \"text\" {\n    expect_contains(\"42 items found\", \"items\")\n    expect_lines(\"a\\nb\\n\", \"a\\nb\\n\")\n}\n\ntest \"snapshots\" {\n    let dir = fs.temp_path(\"nxsnap-\")\n    try snapshot_in(dir, \"first\", \"one\\ntwo\\n\")\n    expect(fs.exists(fs.join(dir, \"first.txt\")))\n    try snapshot_in(dir, \"first\", \"one\\ntwo\\n\")\n    try fs.remove_all(dir)\n}\n";
static const char nx_str_1063[11343] = "// std.text: UTF-8 text by code point, written in Nexium.\n//\n// `import std.text` then:\n//\n//     let n = text.char_count(\"h\303\251llo\")            // 5, not 6\n//     for cp in text.chars(\"h\303\251llo\") { ... }        // code points as u32\n//     let w = text.width(\"\346\227\245\346\234\254\350\252\236\")                   // 6 columns on a terminal\n//     let s = text.to_upper(\"stra\303\237e\")               // \"STRASSE\" is not attempted: \"STRA\303\237E\"\n//     let t = text.truncate(\"h\303\251llo w\303\266rld\", 5)       // \"h\303\251llo\", never mid-character\n//     let ok = text.is_valid(\"...\")\n//\n// Strings are bytes; this module reads them as UTF-8, tolerating bad input\n// (an invalid byte decodes as U+FFFD and advances one byte). Case mapping\n// covers ASCII, Latin-1, Latin Extended-A, Greek and Cyrillic, which is what\n// is cheap to do without tables. `width` follows the usual terminal\n// convention: East Asian wide and fullwidth forms take two columns,\n// combining marks and zero-width characters take none.\n\npub const REPLACEMENT: u32 = 0xFFFD\n\n/// A decoded code point and the number of bytes it took.\npub struct Decoded {\n    cp: u32\n    len: usize\n}\n\n/// Decode the code point starting at byte `i`. Invalid input yields\n/// U+FFFD with length 1 so callers always make progress.\npub fn decode_at(s: []u8, i: usize) -> Decoded {\n    if i >= s.len { return Decoded{ .cp = REPLACEMENT, .len = 0 } }\n    let b0 = s[i]\n    if b0 < 0x80 { return Decoded{ .cp = b0 as u32, .len = 1 } }\n    var need: usize = 0\n    var cp: u32 = 0\n    var min: u32 = 0\n    if b0 >= 0xC2 and b0 <= 0xDF {\n        need = 1\n        cp = (b0 & 0x1F) as u32\n        min = 0x80\n    } else if b0 >= 0xE0 and b0 <= 0xEF {\n        need = 2\n        cp = (b0 & 0x0F) as u32\n        min = 0x800\n    } else if b0 >= 0xF0 and b0 <= 0xF4 {\n        need = 3\n        cp = (b0 & 0x07) as u32\n        min = 0x10000\n    } else {\n        return Decoded{ .cp = REPLACEMENT, .len = 1 }\n    }\n    var k: usize = 1\n    while k <= need {\n        if i + k >= s.len { return Decoded{ .cp = REPLACEMENT, .len = 1 } }\n        let b = s[i + k]\n        if b < 0x80 or b > 0xBF { return Decoded{ .cp = REPLACEMENT, .len = 1 } }\n        cp = (cp << 6) | ((b & 0x3F) as u32)\n        k += 1\n    }\n    if cp < min or cp > 0x10FFFF or (cp >= 0xD800 and cp <= 0xDFFF) { return Decoded{ .cp = REPLACEMENT, .len = 1 } }\n    return Decoded{ .cp = cp, .len = need + 1 }\n}\n\n/// Append a code point as UTF-8.\npub fn push(out: *mut String, cp: u32) {\n    if cp < 0x80 {\n        out.push_byte(cp as u8)\n    } else if cp < 0x800 {\n        out.push_byte((0xC0 | (cp >> 6)) as u8)\n        out.push_byte((0x80 | (cp & 0x3F)) as u8)\n    } else if cp < 0x10000 {\n        out.push_byte((0xE0 | (cp >> 12)) as u8)\n        out.push_byte((0x80 | ((cp >> 6) & 0x3F)) as u8)\n        out.push_byte((0x80 | (cp & 0x3F)) as u8)\n    } else {\n        out.push_byte((0xF0 | (cp >> 18)) as u8)\n        out.push_byte((0x80 | ((cp >> 12) & 0x3F)) as u8)\n        out.push_byte((0x80 | ((cp >> 6) & 0x3F)) as u8)\n        out.push_byte((0x80 | (cp & 0x3F)) as u8)\n    }\n}\n\n/// A code point as a String.\npub fn encode(cp: u32) -> String {\n    var out = String.new()\n    push(&mut out, cp)\n    return out\n}\n\n/// Is the text well-formed UTF-8?\npub fn is_valid(s: []u8) -> bool {\n    var i: usize = 0\n    while i < s.len {\n        let d = decode_at(s, i)\n        if d.cp == REPLACEMENT and (d.len == 1 and s[i] != 0xEF) { return false }\n        i += d.len\n    }\n    return true\n}\n\n/// All code points.\npub fn chars(s: []u8) -> List(u32) {\n    var out = List(u32).new()\n    var i: usize = 0\n    while i < s.len {\n        let d = decode_at(s, i)\n        out.append(d.cp)\n        i += d.len\n    }\n    return out\n}\n\n/// The number of code points.\npub fn char_count(s: []u8) -> usize {\n    var n: usize = 0\n    var i: usize = 0\n    while i < s.len {\n        i += decode_at(s, i).len\n        n += 1\n    }\n    return n\n}\n\n/// The byte offset of the `n`th code point (or `s.len` when past the end).\npub fn byte_offset(s: []u8, n: usize) -> usize {\n    var i: usize = 0\n    var k: usize = 0\n    while i < s.len and k < n {\n        i += decode_at(s, i).len\n        k += 1\n    }\n    return i\n}\n\n/// The `n`th code point, or null.\npub fn char_at(s: []u8, n: usize) -> ?u32 {\n    let i = byte_offset(s, n)\n    if i >= s.len { return null }\n    return decode_at(s, i).cp\n}\n\n/// Code points `from` (inclusive) to `to` (exclusive), as a slice of `s`.\npub fn slice(s: []u8, from: usize, to: usize) -> []u8 {\n    let a = byte_offset(s, from)\n    let b = byte_offset(s, to)\n    if b < a { return s[a..a] }\n    return s[a..b]\n}\n\n/// The first `n` code points; never cuts a character in half.\npub fn truncate(s: []u8, n: usize) -> []u8 {\n    return s[0..byte_offset(s, n)]\n}\n\n/// The code points in reverse order.\npub fn reverse(s: []u8) -> String {\n    let cps = chars(s)\n    var out = String.with_capacity(s.len)\n    var i = cps.len\n    while i > 0 {\n        i -= 1\n        push(&mut out, cps[i])\n    }\n    return out\n}\n\n// ------------------------------------------------------------------ width\n\nfn in_range(cp: u32, lo: u32, hi: u32) -> bool {\n    return cp >= lo and cp <= hi\n}\n\n/// Does the code point take no columns (combining marks, zero-width, controls)?\npub fn is_zero_width(cp: u32) -> bool {\n    if cp == 0 or cp == 0x200B or cp == 0x200C or cp == 0x200D or cp == 0xFEFF { return true }\n    if cp < 0x20 or in_range(cp, 0x7F, 0x9F) { return true }\n    return in_range(cp, 0x0300, 0x036F) or in_range(cp, 0x0483, 0x0489) or in_range(cp, 0x0591, 0x05BD)\n        or in_range(cp, 0x0610, 0x061A) or in_range(cp, 0x064B, 0x065F) or in_range(cp, 0x0E31, 0x0E3A)\n        or in_range(cp, 0x1AB0, 0x1AFF) or in_range(cp, 0x1DC0, 0x1DFF) or in_range(cp, 0x20D0, 0x20FF)\n        or in_range(cp, 0xFE00, 0xFE0F) or in_range(cp, 0xFE20, 0xFE2F) or in_range(cp, 0xE0100, 0xE01EF)\n}\n\n/// Does the code point take two columns (East Asian wide and fullwidth)?\npub fn is_wide(cp: u32) -> bool {\n    return in_range(cp, 0x1100, 0x115F) or in_range(cp, 0x2E80, 0x303E) or in_range(cp, 0x3041, 0x33FF)\n        or in_range(cp, 0x3400, 0x4DBF) or in_range(cp, 0x4E00, 0x9FFF) or in_range(cp, 0xA000, 0xA4CF)\n        or in_range(cp, 0xAC00, 0xD7A3) or in_range(cp, 0xF900, 0xFAFF) or in_range(cp, 0xFE30, 0xFE4F)\n        or in_range(cp, 0xFF00, 0xFF60) or in_range(cp, 0xFFE0, 0xFFE6) or in_range(cp, 0x1F300, 0x1F64F)\n        or in_range(cp, 0x1F900, 0x1F9FF) or in_range(cp, 0x20000, 0x2FFFD) or in_range(cp, 0x30000, 0x3FFFD)\n}\n\n/// Columns a code point takes on a terminal: 0, 1 or 2.\npub fn char_width(cp: u32) -> usize {\n    if is_zero_width(cp) { return 0 }\n    if is_wide(cp) { return 2 }\n    return 1\n}\n\n/// Columns the text takes on a terminal.\npub fn width(s: []u8) -> usize {\n    var w: usize = 0\n    var i: usize = 0\n    while i < s.len {\n        let d = decode_at(s, i)\n        w += char_width(d.cp)\n        i += d.len\n    }\n    return w\n}\n\n/// Pad on the right to `columns` terminal columns (by width, not bytes).\npub fn pad_right(s: []u8, columns: usize) -> String {\n    var out = String.from(s)\n    var w = width(s)\n    while w < columns {\n        out.push_byte(' ')\n        w += 1\n    }\n    return out\n}\n\n// ------------------------------------------------------------------ case\n\n/// Upper-case a code point where the mapping is a fixed offset: ASCII,\n/// Latin-1, Latin Extended-A (pairs), Greek, Cyrillic.\npub fn upper_char(cp: u32) -> u32 {\n    if in_range(cp, 'a' as u32, 'z' as u32) { return cp - 32 }\n    if cp < 0x80 { return cp }\n    if in_range(cp, 0xE0, 0xFE) and cp != 0xF7 { return cp - 32 }\n    if cp == 0xFF { return 0x178 }\n    if in_range(cp, 0x100, 0x137) or in_range(cp, 0x14A, 0x177) { return if cp % 2 == 1 { cp - 1 } else { cp } }\n    if in_range(cp, 0x139, 0x148) or in_range(cp, 0x179, 0x17E) { return if cp % 2 == 0 { cp - 1 } else { cp } }\n    if in_range(cp, 0x3B1, 0x3C9) and cp != 0x3C2 { return cp - 32 }\n    if cp == 0x3C2 { return 0x3A3 }\n    if in_range(cp, 0x430, 0x44F) { return cp - 32 }\n    if in_range(cp, 0x450, 0x45F) { return cp - 80 }\n    return cp\n}\n\n/// Lower-case a code point; the inverse of `upper_char`.\npub fn lower_char(cp: u32) -> u32 {\n    if in_range(cp, 'A' as u32, 'Z' as u32) { return cp + 32 }\n    if cp < 0x80 { return cp }\n    if in_range(cp, 0xC0, 0xDE) and cp != 0xD7 { return cp + 32 }\n    if cp == 0x178 { return 0xFF }\n    if in_range(cp, 0x100, 0x137) or in_range(cp, 0x14A, 0x177) { return if cp % 2 == 0 { cp + 1 } else { cp } }\n    if in_range(cp, 0x139, 0x148) or in_range(cp, 0x179, 0x17E) { return if cp % 2 == 1 { cp + 1 } else { cp } }\n    if in_range(cp, 0x391, 0x3A9) { return cp + 32 }\n    if in_range(cp, 0x410, 0x42F) { return cp + 32 }\n    if in_range(cp, 0x400, 0x40F) { return cp + 80 }\n    return cp\n}\n\nfn map_chars(s: []u8, upper: bool) -> String {\n    var out = String.with_capacity(s.len)\n    var i: usize = 0\n    while i < s.len {\n        let d = decode_at(s, i)\n        push(&mut out, if upper { upper_char(d.cp) } else { lower_char(d.cp) })\n        i += d.len\n    }\n    return out\n}\n\npub fn to_upper(s: []u8) -> String {\n    return map_chars(s, true)\n}\n\npub fn to_lower(s: []u8) -> String {\n    return map_chars(s, false)\n}\n\n/// Compare ignoring case, using the same mapping as `to_lower`.\npub fn eq_ignore_case(a: []u8, b: []u8) -> bool {\n    var i: usize = 0\n    var j: usize = 0\n    while i < a.len and j < b.len {\n        let x = decode_at(a, i)\n        let y = decode_at(b, j)\n        if lower_char(x.cp) != lower_char(y.cp) { return false }\n        i += x.len\n        j += y.len\n    }\n    return i == a.len and j == b.len\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"decode and encode\" {\n    expect_eq(char_count(\"h\303\251llo\"), 5)\n    expect_eq(char_count(\"\346\227\245\346\234\254\350\252\236\"), 3)\n    expect_eq(chars(\"a\303\251\346\227\245\360\237\230\200\").len, 4)\n    expect_eq(chars(\"a\303\251\346\227\245\360\237\230\200\")[3], 0x1F600)\n    expect_eq(encode(0xE9), \"\303\251\")\n    expect_eq(encode(0x65E5), \"\346\227\245\")\n    expect_eq(encode(0x1F600), \"\360\237\230\200\")\n    expect(is_valid(\"h\303\251llo \346\227\245\346\234\254\"))\n    expect(!is_valid(b\"\\xff\\xfe\"))\n    expect(!is_valid(b\"\\xe6\\x97\"))\n    let bad = decode_at(b\"\\xff\", 0)\n    expect_eq(bad.cp, REPLACEMENT)\n    expect_eq(bad.len, 1)\n    expect_eq(char_at(\"h\303\251llo\", 1).?, 0xE9)\n    expect(char_at(\"h\303\251\", 2) == null)\n    expect_eq(slice(\"h\303\251llo w\303\266rld\", 6, 11), \"w\303\266rld\")\n    expect_eq(truncate(\"h\303\251llo w\303\266rld\", 5), \"h\303\251llo\")\n    expect_eq(reverse(\"h\303\251llo\"), \"oll\303\251h\")\n    expect_eq(byte_offset(\"h\303\251llo\", 2), 3)\n}\n\ntest \"width\" {\n    expect_eq(width(\"hello\"), 5)\n    expect_eq(width(\"\346\227\245\346\234\254\350\252\236\"), 6)\n    expect_eq(width(\"e\\u{301}\"), 1)\n    expect_eq(width(\"a\\u{200B}b\"), 2)\n    expect_eq(char_width(0x1F600), 2)\n    expect_eq(pad_right(\"\346\227\245\346\234\254\", 6), \"\346\227\245\346\234\254  \")\n}\n\ntest \"case\" {\n    expect_eq(to_upper(\"h\303\251llo w\303\266rld\"), \"H\303\211LLO W\303\226RLD\")\n    expect_eq(to_lower(\"\303\200\303\211\303\216\303\225\303\234\"), \"\303\240\303\251\303\256\303\265\303\274\")\n    expect_eq(to_upper(\"stra\303\237e\"), \"STRA\303\237E\")\n    expect_eq(to_upper(\"\316\261\316\262\316\263\"), \"\316\221\316\222\316\223\")\n    expect_eq(to_lower(\"\316\221\316\222\316\223\316\243\"), \"\316\261\316\262\316\263\317\203\")\n    expect_eq(to_upper(\"\320\277\321\200\320\270\320\262\320\265\321\202\"), \"\320\237\320\240\320\230\320\222\320\225\320\242\")\n    expect_eq(to_lower(\"\320\237\320\240\320\230\320\222\320\225\320\242 \320\201\320\226\"), \"\320\277\321\200\320\270\320\262\320\265\321\202 \321\221\320\266\")\n    expect_eq(to_upper(\"\305\202\303\263d\305\272\"), \"\305\201\303\223D\305\271\")\n    expect_eq(to_lower(\"\305\201\303\223D\305\271\"), \"\305\202\303\263d\305\272\")\n    expect(eq_ignore_case(\"H\303\251llo\", \"h\303\211LLO\"))\n    expect(!eq_ignore_case(\"H\303\251llo\", \"hello\"))\n    expect_eq(upper_char('a' as u32), 'A' as u32)\n    expect_eq(lower_char(0x3A3), 0x3C3)\n}\n";
static const char nx_str_1064[8112] = "// std.thread: threads, channels and mutexes, written in Nexium over the\n// `thread.*` and `sync.*` primitives.\n//\n// `import std.thread` then:\n//\n//     fn work(job: *mut Job) -> i64 { ... }\n//     var t = thread.spawn(Job, i64, work, Job{ .from = 0, .to = 1000 })\n//     let total = t.join()                        // the function's result\n//\n//     fn produce(p: *mut Producer) { ... }        // no result: a Worker\n//     var ch = thread.channel(String)             // shared by pointer\n//     var producer = thread.run(Producer, produce, Producer{ .out = &mut ch })\n//     let msg = ch.recv() orelse break            // null once closed and drained\n//     producer.join()\n//\n//     var counter = thread.mutex(i64, 0)\n//     let n = counter.lock()                      // *mut i64 while held\n//     n.* += 1\n//     counter.unlock()\n//\n// A thread function takes a pointer to its argument, which the `Thread`\n// owns until `join` returns the result. Channels and mutexes are values\n// that threads share by pointer; the owner must join every thread using\n// them before letting them go out of scope, and call `free` when done.\n// Panics inside a thread surface from `join`.\n\n/// The argument, function and result of one thread.\npub struct Task(T, R){\n    f: fn(*mut T) -> R\n    arg: T\n    result: List(R)\n}\n\n/// A running or finished thread.\npub struct Thread(T, R){\n    cell: List(Task(T, R))\n    handle: i64\n    joined: bool\n}\n\n/// Run `f(&mut arg)` on a new thread.\npub fn spawn(comptime T: type, comptime R: type, f: fn(*mut T) -> R, own arg: T) -> Thread(T, R) {\n    var cell = List(Task(T, R)).with_capacity(1)\n    cell.append(Task(T, R){ .f = f, .arg = arg, .result = List(R).new() })\n    let entry = |task: *mut Task(T, R)| {\n        let g = task.f\n        let r = g(&mut task.arg)\n        task.result.append(r)\n    }\n    let handle = thread.start(entry, &mut cell[0])\n    return Thread(T, R){ .cell = cell, .handle = handle, .joined = false }\n}\n\nimpl(T, R) Thread(T, R) {\n    /// Wait for the thread and take its result. Joining twice panics.\n    pub fn join(self: *mut Self) -> R {\n        if self.joined { panic(\"thread joined twice\") }\n        thread.join(self.handle)\n        self.joined = true\n        return self.cell[0].result.pop().?\n    }\n\n    /// The argument after the thread finished (for results written in place).\n    pub fn arg(self: *Self) -> *T {\n        if !self.joined { panic(\"the argument is shared with the running thread until join\") }\n        return &self.cell[0].arg\n    }\n}\n\n/// The argument and function of a thread without a result.\npub struct WorkerTask(T){\n    f: fn(*mut T) -> void\n    arg: T\n}\n\n/// A running or finished thread whose function returns nothing.\npub struct Worker(T){\n    cell: List(WorkerTask(T))\n    handle: i64\n    joined: bool\n}\n\n/// Run `f(&mut arg)` on a new thread, for functions without a result.\npub fn run(comptime T: type, f: fn(*mut T) -> void, own arg: T) -> Worker(T) {\n    var cell = List(WorkerTask(T)).with_capacity(1)\n    cell.append(WorkerTask(T){ .f = f, .arg = arg })\n    let entry = |task: *mut WorkerTask(T)| {\n        let g = task.f\n        g(&mut task.arg)\n    }\n    let handle = thread.start(entry, &mut cell[0])\n    return Worker(T){ .cell = cell, .handle = handle, .joined = false }\n}\n\nimpl(T) Worker(T) {\n    /// Wait for the thread. Joining twice panics.\n    pub fn join(self: *mut Self) {\n        if self.joined { panic(\"thread joined twice\") }\n        thread.join(self.handle)\n        self.joined = true\n    }\n\n    /// The argument after the thread finished (for results written in place).\n    pub fn arg(self: *Self) -> *T {\n        if !self.joined { panic(\"the argument is shared with the running thread until join\") }\n        return &self.cell[0].arg\n    }\n}\n\n/// The number of hardware threads.\npub fn count() -> usize {\n    return thread.count()\n}\n\n// ------------------------------------------------------------------ channels\n\n/// An unbounded queue between threads. `recv` blocks while it is empty\n/// and open, and returns null once it is closed and drained.\npub struct Channel(T){\n    items: List(T)\n    lock: i64\n    cond: i64\n    closed: bool\n}\n\npub fn channel(comptime T: type) -> Channel(T) {\n    return Channel(T){ .items = List(T).new(), .lock = sync.mutex_new(), .cond = sync.cond_new(), .closed = false }\n}\n\nimpl(T) Channel(T) {\n    pub fn send(self: *mut Self, own value: T) {\n        sync.lock(self.lock)\n        self.items.append(value)\n        sync.signal(self.cond)\n        sync.unlock(self.lock)\n    }\n\n    /// The next value, waiting for one; null when closed and empty.\n    pub fn recv(self: *mut Self) -> ?T {\n        sync.lock(self.lock)\n        while self.items.len == 0 and !self.closed { sync.wait(self.cond, self.lock) }\n        var out: ?T = null\n        if self.items.len > 0 { out = self.items.remove(0) }\n        sync.unlock(self.lock)\n        return out\n    }\n\n    /// The next value if one is queued, without waiting.\n    pub fn try_recv(self: *mut Self) -> ?T {\n        sync.lock(self.lock)\n        var out: ?T = null\n        if self.items.len > 0 { out = self.items.remove(0) }\n        sync.unlock(self.lock)\n        return out\n    }\n\n    /// No more values will be sent; receivers drain what is left, then see null.\n    pub fn close(self: *mut Self) {\n        sync.lock(self.lock)\n        self.closed = true\n        sync.broadcast(self.cond)\n        sync.unlock(self.lock)\n    }\n\n    pub fn len(self: *mut Self) -> usize {\n        sync.lock(self.lock)\n        let n = self.items.len\n        sync.unlock(self.lock)\n        return n\n    }\n\n    /// Release the lock and condition variable; after every user has stopped.\n    pub fn free(self: *mut Self) {\n        sync.cond_free(self.cond)\n        sync.mutex_free(self.lock)\n    }\n}\n\n// ------------------------------------------------------------------ mutexes\n\n/// A value guarded by a lock.\npub struct Mutex(T){\n    lock: i64\n    value: T\n}\n\npub fn mutex(comptime T: type, own value: T) -> Mutex(T) {\n    return Mutex(T){ .lock = sync.mutex_new(), .value = value }\n}\n\nimpl(T) Mutex(T) {\n    /// Take the lock; the pointer is valid until `unlock`.\n    pub fn lock(self: *mut Self) -> *mut T{\n        sync.lock(self.lock)\n        return &mut self.value\n    }\n\n    pub fn unlock(self: *mut Self) {\n        sync.unlock(self.lock)\n    }\n\n    /// Release the lock; after every user has stopped.\n    pub fn free(self: *mut Self) {\n        sync.mutex_free(self.lock)\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\nstruct Range {\n    from: i64\n    to: i64\n}\n\nfn sum_range(r: *mut Range) -> i64 {\n    var s: i64 = 0\n    var i = r.from\n    while i < r.to {\n        s += i\n        i += 1\n    }\n    return s\n}\n\nstruct Producer {\n    out: *mut Channel(i64)\n    n: i64\n}\n\nfn produce(p: *mut Producer) {\n    var i: i64 = 0\n    while i < p.n {\n        p.out.send(i)\n        i += 1\n    }\n    p.out.close()\n}\n\nstruct Bumper {\n    counter: *mut Mutex(i64)\n    times: i64\n}\n\nfn bump(b: *mut Bumper) {\n    var i: i64 = 0\n    while i < b.times {\n        let n = b.counter.lock()\n        n.*+= 1\n        b.counter.unlock()\n        i += 1\n    }\n}\n\ntest \"spawn and join\" {\n    var a = spawn(Range, i64, sum_range, Range{ .from = 0, .to = 1000 })\n    var b = spawn(Range, i64, sum_range, Range{ .from = 1000, .to = 2000 })\n    let total = a.join() + b.join()\n    expect_eq(total, 1999000)\n    expect(count() >= 1)\n}\n\ntest \"channel\" {\n    var ch = channel(i64)\n    var p = run(Producer, produce, Producer{ .out = &mut ch, .n = 100 })\n    var sum: i64 = 0\n    var got: i64 = 0\n    while true {\n        let v = ch.recv() orelse break\n        sum += v\n        got += 1\n    }\n    p.join()\n    expect_eq(got, 100)\n    expect_eq(sum, 4950)\n    expect(ch.try_recv() == null)\n    ch.free()\n}\n\ntest \"mutex\" {\n    var counter = mutex(i64, 0)\n    var ts = List(Worker(Bumper)).new()\n    for _ in 0..4 {\n        ts.append(run(Bumper, bump, Bumper{ .counter = &mut counter, .times = 2500 }))\n    }\n    for i in 0..ts.len { ts[i].join() }\n    let n = counter.lock()\n    expect_eq(n.*, 10000)\n    counter.unlock()\n    counter.free()\n}\n";
static const char nx_str_1065[17047] = "// std.time: dates, durations and timers, written in Nexium.\n//\n// `import std.time` then:\n//\n//     let now = time.now_utc()                    // a DateTime\n//     println(\"{}\", .{now.iso()})                 // 2026-09-19T04:15:14.123Z\n//     println(\"{}\", .{now.format(\"%Y-%m-%d %H:%M\")})\n//     let local = time.now_local()                // with the machine's UTC offset\n//     let d = time.Duration.minutes(90)\n//     println(\"{}\", .{d.text()})                  // 1h 30m\n//     var sw = time.Stopwatch.start()\n//     ... work ...\n//     println(\"took {}\", .{sw.elapsed().text()})\n//\n// Instants are milliseconds since 1970-01-01T00:00:00Z (`time.now()`), as\n// `i64`; negative values are before the epoch. Calendar arithmetic is the\n// proleptic Gregorian calendar; the only platform call is the local UTC\n// offset, and only `now_local` and `local` use it.\n\n// ------------------------------------------------------------------ calendar\n\n/// A broken-down instant. `offset_min` is the UTC offset the fields are\n/// expressed in (0 for UTC); `to_ms()` accounts for it.\npub struct DateTime {\n    year: i32\n    month: u8\n    day: u8\n    hour: u8\n    minute: u8\n    second: u8\n    millis: u16\n    offset_min: i32\n}\n\npub fn is_leap(year: i32) -> bool {\n    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0\n}\n\npub fn days_in_month(year: i32, month: u8) -> u8 {\n    if month == 2 { return if is_leap(year) { 29 } else { 28 } }\n    if month == 4 or month == 6 or month == 9 or month == 11 { return 30 }\n    return 31\n}\n\nfn floor_div(a: i64, b: i64) -> i64 {\n    var q = a / b\n    if (a % b != 0) and ((a < 0) != (b < 0)) { q -= 1 }\n    return q\n}\n\nfn floor_mod(a: i64, b: i64) -> i64 {\n    return a - floor_div(a, b) * b\n}\n\n/// Days since 1970-01-01 of a civil date (Howard Hinnant's algorithm).\nfn days_from_civil(y0: i32, m: u8, d: u8) -> i64 {\n    var y = y0 as i64\n    if m <= 2 { y -= 1 }\n    let era = floor_div(y, 400)\n    let yoe = y - era * 400\n    let mp = if m > 2 { (m as i64) - 3 } else { (m as i64) + 9 }\n    let doy = (153 * mp + 2) / 5 + (d as i64) - 1\n    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy\n    return era * 146097 + doe - 719468\n}\n\n/// The civil date of a day count since 1970-01-01.\nfn civil_from_days(z0: i64) -> (i32, u8, u8) {\n    let z = z0 + 719468\n    let era = floor_div(z, 146097)\n    let doe = z - era * 146097\n    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365\n    let y = yoe + era * 400\n    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100)\n    let mp = (5 * doy + 2) / 153\n    let d = doy - (153 * mp + 2) / 5 + 1\n    let m = if mp < 10 { mp + 3 } else { mp - 9 }\n    let year = if m <= 2 { y + 1 } else { y }\n    return (year as i32, m as u8, d as u8)\n}\n\n/// Break an instant down in UTC.\npub fn utc(ms: i64) -> DateTime {\n    return with_offset(ms, 0)\n}\n\n/// Break an instant down in the machine's local time zone.\npub fn local(ms: i64) -> DateTime {\n    return with_offset(ms, time.utc_offset(ms) as i32)\n}\n\n/// Break an instant down at a fixed offset in minutes east of UTC.\npub fn with_offset(ms: i64, offset_min: i32) -> DateTime {\n    let shifted = ms + (offset_min as i64) * 60000\n    let days = floor_div(shifted, 86400000)\n    let rem = floor_mod(shifted, 86400000)\n    let ymd = civil_from_days(days)\n    return DateTime{\n        .year = ymd.0,\n        .month = ymd.1,\n        .day = ymd.2,\n        .hour = (rem / 3600000) as u8,\n        .minute = ((rem / 60000) % 60) as u8,\n        .second = ((rem / 1000) % 60) as u8,\n        .millis = (rem % 1000) as u16,\n        .offset_min = offset_min,\n    }\n}\n\n/// The current instant, in UTC.\npub fn now_utc() -> DateTime {\n    return utc(time.now())\n}\n\n/// The current instant, in local time.\npub fn now_local() -> DateTime {\n    return local(time.now())\n}\n\n/// A date at midnight UTC; `null` when the fields do not name a real day.\npub fn date(year: i32, month: u8, day: u8) -> ?DateTime {\n    if month < 1 or month > 12 or day < 1 or day > days_in_month(year, month) { return null }\n    return DateTime{ .year = year, .month = month, .day = day, .hour = 0, .minute = 0, .second = 0, .millis = 0, .offset_min = 0 }\n}\n\nfn pad(out: *mut String, v: i64, width: usize) {\n    var n = if v < 0 { -v } else { v }\n    var digits: usize = 1\n    var t = n\n    while t >= 10 {\n        t /= 10\n        digits += 1\n    }\n    if v < 0 { out.push_byte('-') }\n    while digits < width {\n        out.push_byte('0')\n        digits += 1\n    }\n    out.append(format(\"{}\", .{n}))\n}\n\nconst MONTHS = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\", \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"]\nconst DAYS = [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\"]\n\nimpl DateTime {\n    /// Milliseconds since the epoch (the offset is subtracted back out).\n    pub fn to_ms(self: *Self) -> i64 {\n        let days = days_from_civil(self.year, self.month, self.day)\n        let local_ms = days * 86400000 + (self.hour as i64) * 3600000 + (self.minute as i64) * 60000 + (self.second as i64) * 1000 + (self.millis as i64)\n        return local_ms - (self.offset_min as i64) * 60000\n    }\n\n    /// The same instant expressed in UTC.\n    pub fn to_utc(self: *Self) -> DateTime {\n        return utc(self.to_ms())\n    }\n\n    /// Day of the week, 0 = Monday ... 6 = Sunday.\n    pub fn weekday(self: *Self) -> u8 {\n        let days = days_from_civil(self.year, self.month, self.day)\n        return floor_mod(days + 3, 7) as u8\n    }\n\n    /// Day of the year, 1-based.\n    pub fn day_of_year(self: *Self) -> u16 {\n        var n: u16 = self.day as u16\n        var m: u8 = 1\n        while m < self.month {\n            n += days_in_month(self.year, m) as u16\n            m += 1\n        }\n        return n\n    }\n\n    /// `YYYY-MM-DD`.\n    pub fn date_text(self: *Self) -> String {\n        var out = String.new()\n        pad(&mut out, self.year as i64, 4)\n        out.push_byte('-')\n        pad(&mut out, self.month as i64, 2)\n        out.push_byte('-')\n        pad(&mut out, self.day as i64, 2)\n        return out\n    }\n\n    /// `HH:MM:SS`.\n    pub fn time_text(self: *Self) -> String {\n        var out = String.new()\n        pad(&mut out, self.hour as i64, 2)\n        out.push_byte(':')\n        pad(&mut out, self.minute as i64, 2)\n        out.push_byte(':')\n        pad(&mut out, self.second as i64, 2)\n        return out\n    }\n\n    /// The offset as `Z`, or `+HH:MM` / `-HH:MM`.\n    pub fn offset_text(self: *Self) -> String {\n        var out = String.new()\n        if self.offset_min == 0 {\n            out.push_byte('Z')\n            return out\n        }\n        let o = self.offset_min as i64\n        out.push_byte(if o < 0 { '-' } else { '+' })\n        let a = if o < 0 { -o } else { o }\n        pad(&mut out, a / 60, 2)\n        out.push_byte(':')\n        pad(&mut out, a % 60, 2)\n        return out\n    }\n\n    /// ISO 8601 / RFC 3339: `2026-09-19T04:15:14.123Z`, `...+02:00`.\n    pub fn iso(self: *Self) -> String {\n        var out = self.date_text()\n        out.push_byte('T')\n        out.append(self.time_text())\n        if self.millis != 0 {\n            out.push_byte('.')\n            pad(&mut out, self.millis as i64, 3)\n        }\n        out.append(self.offset_text())\n        return out\n    }\n\n    /// strftime-style formatting: `%Y %m %d %H %M %S %3` (millis) `%z` (offset)\n    /// `%a %b` (short day and month names) `%j` (day of year) `%%`.\n    /// Unknown letters are copied through.\n    pub fn format(self: *Self, spec: []u8) -> String {\n        var out = String.new()\n        var i: usize = 0\n        while i < spec.len {\n            let c = spec[i]\n            if c != '%' or i + 1 >= spec.len {\n                out.push_byte(c)\n                i += 1\n                continue\n            }\n            let f = spec[i + 1]\n            i += 2\n            if f == 'Y' { pad(&mut out, self.year as i64, 4) }\n            else if f == 'm' { pad(&mut out, self.month as i64, 2) }\n            else if f == 'd' { pad(&mut out, self.day as i64, 2) }\n            else if f == 'H' { pad(&mut out, self.hour as i64, 2) }\n            else if f == 'M' { pad(&mut out, self.minute as i64, 2) }\n            else if f == 'S' { pad(&mut out, self.second as i64, 2) }\n            else if f == '3' { pad(&mut out, self.millis as i64, 3) }\n            else if f == 'j' { pad(&mut out, self.day_of_year() as i64, 3) }\n            else if f == 'z' { out.append(self.offset_text()) }\n            else if f == 'a' { out.append(DAYS[self.weekday() as usize]) }\n            else if f == 'b' { out.append(MONTHS[(self.month - 1) as usize]) }\n            else if f == '%' { out.push_byte('%') }\n            else {\n                out.push_byte('%')\n                out.push_byte(f)\n            }\n        }\n        return out\n    }\n}\n\nfn digits(s: []u8, start: usize, n: usize) -> ?i64 {\n    if start + n > s.len { return null }\n    var v: i64 = 0\n    for i in start..start + n {\n        let c = s[i]\n        if c < '0' or c > '9' { return null }\n        v = v * 10 + ((c - '0') as i64)\n    }\n    return v\n}\n\n/// Parse `YYYY-MM-DD`, optionally followed by `THH:MM[:SS[.mmm]]` and an\n/// offset `Z` / `+HH:MM` / `-HH:MM`. Missing parts are zero; `null` when the\n/// text is not a date.\npub fn parse_iso(s: []u8) -> ?DateTime {\n    let year = digits(s, 0, 4) orelse return null\n    if s.len < 10 or s[4] != '-' or s[7] != '-' { return null }\n    let month = digits(s, 5, 2) orelse return null\n    let day = digits(s, 8, 2) orelse return null\n    var dt = date(year as i32, month as u8, day as u8) orelse return null\n    var i: usize = 10\n    if i < s.len and (s[i] == 'T' or s[i] == ' ') {\n        let hour = digits(s, i + 1, 2) orelse return null\n        if i + 3 >= s.len or s[i + 3] != ':' { return null }\n        let minute = digits(s, i + 4, 2) orelse return null\n        if hour > 23 or minute > 59 { return null }\n        dt.hour = hour as u8\n        dt.minute = minute as u8\n        i += 6\n        if i < s.len and s[i] == ':' {\n            let second = digits(s, i + 1, 2) orelse return null\n            if second > 60 { return null }\n            dt.second = second as u8\n            i += 3\n            if i < s.len and s[i] == '.' {\n                var n: usize = 0\n                var ms: i64 = 0\n                while i + 1 + n < s.len and s[i + 1 + n] >= '0' and s[i + 1 + n] <= '9' {\n                    if n < 3 { ms = ms * 10 + ((s[i + 1 + n] - '0') as i64) }\n                    n += 1\n                }\n                if n == 0 { return null }\n                while n < 3 {\n                    ms *= 10\n                    n += 1\n                }\n                dt.millis = ms as u16\n                i += 1 + n\n            }\n        }\n    }\n    if i < s.len {\n        let c = s[i]\n        if c == 'Z' {\n            i += 1\n        } else if c == '+' or c == '-' {\n            let oh = digits(s, i + 1, 2) orelse return null\n            if i + 3 >= s.len or s[i + 3] != ':' { return null }\n            let om = digits(s, i + 4, 2) orelse return null\n            var off = (oh * 60 + om) as i32\n            if c == '-' { off = -off }\n            dt.offset_min = off\n            i += 6\n        }\n    }\n    if i != s.len { return null }\n    return dt\n}\n\n// ------------------------------------------------------------------ durations\n\n/// A span of time in milliseconds; negative means \"before\".\npub struct Duration {\n    ms: i64\n}\n\nimpl Duration {\n    pub fn millis(n: i64) -> Duration { return Duration{ .ms = n } }\n    pub fn seconds(n: i64) -> Duration { return Duration{ .ms = n * 1000 } }\n    pub fn minutes(n: i64) -> Duration { return Duration{ .ms = n * 60000 } }\n    pub fn hours(n: i64) -> Duration { return Duration{ .ms = n * 3600000 } }\n    pub fn days(n: i64) -> Duration { return Duration{ .ms = n * 86400000 } }\n\n    /// The span from `a` to `b` (instants in ms).\n    pub fn between(a: i64, b: i64) -> Duration { return Duration{ .ms = b - a } }\n\n    /// The span from an instant to now.\n    pub fn since(ms: i64) -> Duration { return Duration{ .ms = time.now() - ms } }\n\n    pub fn total_seconds(self: *Self) -> f64 { return (self.ms as f64) / 1000.0 }\n    pub fn total_minutes(self: *Self) -> f64 { return (self.ms as f64) / 60000.0 }\n    pub fn total_hours(self: *Self) -> f64 { return (self.ms as f64) / 3600000.0 }\n\n    pub fn plus(self: *Self, other: Duration) -> Duration { return Duration{ .ms = self.ms + other.ms } }\n    pub fn minus(self: *Self, other: Duration) -> Duration { return Duration{ .ms = self.ms - other.ms } }\n\n    /// Human text: `250ms`, `3.5s`, `2m 05s`, `1h 02m`, `3d 04h`.\n    pub fn text(self: *Self) -> String {\n        var out = String.new()\n        var ms = self.ms\n        if ms < 0 {\n            out.push_byte('-')\n            ms = -ms\n        }\n        if ms < 1000 {\n            out.append(format(\"{}ms\", .{ms}))\n            return out\n        }\n        if ms < 60000 {\n            let tenths = (ms + 50) / 100\n            out.append(format(\"{}.{}s\", .{tenths / 10, tenths % 10}))\n            return out\n        }\n        let secs = ms / 1000\n        if secs < 3600 {\n            out.append(format(\"{}m \", .{secs / 60}))\n            pad(&mut out, secs % 60, 2)\n            out.push_byte('s')\n            return out\n        }\n        let mins = secs / 60\n        if mins < 1440 {\n            out.append(format(\"{}h \", .{mins / 60}))\n            pad(&mut out, mins % 60, 2)\n            out.push_byte('m')\n            return out\n        }\n        let hours = mins / 60\n        out.append(format(\"{}d \", .{hours / 24}))\n        pad(&mut out, hours % 24, 2)\n        out.push_byte('h')\n        return out\n    }\n}\n\n/// `instant + duration`.\npub fn add(ms: i64, d: Duration) -> i64 {\n    return ms + d.ms\n}\n\n// ------------------------------------------------------------------ timers\n\n/// Measures elapsed time on the monotonic clock.\npub struct Stopwatch {\n    start_ns: u64\n}\n\nimpl Stopwatch {\n    pub fn start() -> Stopwatch {\n        return Stopwatch{ .start_ns = time.monotonic() }\n    }\n\n    /// Elapsed time in milliseconds, fractional.\n    pub fn elapsed_ms(self: *Self) -> f64 {\n        return ((time.monotonic() - self.start_ns) as f64) / 1000000.0\n    }\n\n    /// Elapsed time as a Duration (whole milliseconds).\n    pub fn elapsed(self: *Self) -> Duration {\n        return Duration{ .ms = ((time.monotonic() - self.start_ns) / 1000000) as i64 }\n    }\n\n    /// Restart and return what had elapsed.\n    pub fn lap(self: *mut Self) -> Duration {\n        let d = self.elapsed()\n        self.start_ns = time.monotonic()\n        return d\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"epoch and round trips\" {\n    let e = utc(0)\n    expect_eq(e.year, 1970)\n    expect_eq(e.month, 1)\n    expect_eq(e.day, 1)\n    expect_eq(e.weekday(), 3)\n    expect_eq(e.iso(), \"1970-01-01T00:00:00Z\")\n    let t = utc(1789791314123)\n    expect_eq(t.iso(), \"2026-09-19T04:15:14.123Z\")\n    expect_eq(t.weekday(), 5)\n    expect_eq(t.day_of_year(), 262)\n    expect_eq(t.to_ms(), 1789791314123)\n    let b = utc(-1)\n    expect_eq(b.iso(), \"1969-12-31T23:59:59.999Z\")\n    expect_eq(b.to_ms(), -1)\n    let leap = utc(1709208000000)\n    expect_eq(leap.date_text(), \"2024-02-29\")\n    expect_eq(leap.to_ms(), 1709208000000)\n    let old = utc(-11676096000000)\n    expect_eq(old.date_text(), \"1600-01-01\")\n    expect_eq(old.to_ms(), -11676096000000)\n    expect(is_leap(2000))\n    expect(!is_leap(1900))\n    expect_eq(days_in_month(2024, 2), 29)\n}\n\ntest \"offsets and formatting\" {\n    let t = with_offset(1789791314123, 120)\n    expect_eq(t.hour, 6)\n    expect_eq(t.iso(), \"2026-09-19T06:15:14.123+02:00\")\n    expect_eq(t.to_ms(), 1789791314123)\n    expect_eq(t.to_utc().hour, 4)\n    let m = with_offset(1789791314123, -330)\n    expect_eq(m.offset_text(), \"-05:30\")\n    expect_eq(t.format(\"%Y-%m-%d %H:%M:%S.%3 %a %b %j %z 100%%\"), \"2026-09-19 06:15:14.123 Sat Sep 262 +02:00 100%\")\n    expect_eq(t.time_text(), \"06:15:14\")\n}\n\ntest \"parsing\" {\n    let a = parse_iso(\"2026-09-19T04:15:14.123Z\").?\n    expect_eq(a.to_ms(), 1789791314123)\n    let b = parse_iso(\"2026-09-19 06:15:14+02:00\").?\n    expect_eq(b.to_ms(), 1789791314123 - 123)\n    let c = parse_iso(\"2024-02-29\").?\n    expect_eq(c.date_text(), \"2024-02-29\")\n    expect(parse_iso(\"2023-02-29\") == null)\n    expect(parse_iso(\"2024-13-01\") == null)\n    expect(parse_iso(\"nope\") == null)\n    expect(parse_iso(\"2024-02-29T25:00\") == null)\n    let d = parse_iso(\"2024-02-29T12:30\").?\n    expect_eq(d.time_text(), \"12:30:00\")\n}\n\ntest \"durations\" {\n    expect_eq(Duration.millis(250).text(), \"250ms\")\n    expect_eq(Duration.millis(3500).text(), \"3.5s\")\n    expect_eq(Duration.seconds(125).text(), \"2m 05s\")\n    expect_eq(Duration.minutes(62).text(), \"1h 02m\")\n    expect_eq(Duration.hours(76).text(), \"3d 04h\")\n    expect_eq(Duration.millis(-1500).text(), \"-1.5s\")\n    expect_eq(Duration.between(1000, 4000).ms, 3000)\n    expect_eq(Duration.minutes(1).plus(Duration.seconds(30)).ms, 90000)\n    expect_eq(add(1000, Duration.seconds(2)), 3000)\n    var sw = Stopwatch.start()\n    let d = sw.lap()\n    expect(d.ms >= 0)\n    expect(sw.elapsed_ms() >= 0.0)\n}\n";
